-- Uldum spawns, part 8 of 8: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `waypoint_data` WHERE (`id` > 91246660 OR (`id` = 91246660 AND `point` >= 6)) AND (`id` < 91255140 OR (`id` = 91255140 AND `point` <= 8));
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` BETWEEN -9120382 AND -9120381;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 1031000 AND 1031433;
DELETE FROM `pool_template` WHERE `entry` BETWEEN 312000 AND 312001;
DELETE FROM `pool_creature` WHERE `guid` BETWEEN 9125515 AND 9126039;








